ALTER POLICY "memory_review_receipts_agent" ON "memory_review_receipts" TO nautilo_agent USING ("memory_review_receipts"."agent_id" = app_current_agent_id() AND EXISTS (SELECT 1 FROM actors a WHERE a.id::text = "memory_review_receipts"."actor_id" AND a.owner_id = app_current_user_id() AND a.kind = 'user')) WITH CHECK ("memory_review_receipts"."outcome" = 'published' AND "memory_review_receipts"."agent_id" = app_current_agent_id() AND EXISTS (SELECT 1 FROM actors a WHERE a.id::text = "memory_review_receipts"."actor_id" AND a.owner_id = app_current_user_id() AND a.kind = 'user'));